{
  "name": "可变控制针阀",
  "name_en": "Variable Controlled Needle Valve",
  "manufacturer": "",
  "description": "一种用于真空系统的可调针阀，用于连续控制两侧气体体积之间的流量，而不是仅进行全开或全关切换。常用于真空管路中的气体导入、抽气平衡或细致流量调节。",
  "description_en": "An adjustable needle valve for vacuum systems that continuously controls flow between two gas volumes rather than simply switching fully open or closed. It is commonly used for gas dosing, pumping balance, or fine flow regulation in vacuum lines.",
  "actions": [
    {
      "action_name": "auto-check_value",
      "description": "检查给定阀门设定值是否有效。",
      "description_en": "Check whether the requested valve setpoint/value is valid."
    },
    {
      "action_name": "auto-interlocked",
      "description": "获取阀门是否处于联锁状态。",
      "description_en": "Get whether the valve is in an interlocked state."
    },
    {
      "action_name": "auto-calc_lightpath_state",
      "description": "计算阀门当前对应的光路状态。",
      "description_en": "Calculate the current lightpath state associated with the valve."
    },
    {
      "action_name": "auto-close_override",
      "description": "设置阀门关闭覆盖状态。",
      "description_en": "Set the valve close-override state."
    }
  ],
  "tag_hints": [
    "vacuum valve",
    "needle valve",
    "variable flow control",
    "gas dosing",
    "vacuum system",
    "fine flow regulation"
  ]
}

